 import React, { useEffect, useState } from 'react';
 import { useNavigation } from '../hooks/useNavigation';
 import api from '../utils/api';
 import PageLayout from '../components/PageLayout';
 import PageHeader from '../components/PageHeader';
 import GlassyCard from '../components/GlassyCard';
 import IframeModal from '../components/IframeModal';
 import styles from './dve-list.module.css';

 const STATUS_COLORS = {
   online: '#4caf50',
 };

 const TEE_ICONS = {
   sgx: '🔒',
   'sev-snp': '🛡️',
   tdx: '🔐',
   software: '💻',
   'browser-dve': '🌐',
 };

 export default function DVEList() {
   const { activePage } = useNavigation('dve-list');
   const [searchQuery, setSearchQuery] = useState('');
   const [activeNodes, setActiveNodes] = useState([]);
+  const [allNodes, setAllNodes] = useState([]);
   const [isLoading, setIsLoading] = useState(true);
   const [error, setError] = useState('');
   const [modal, setModal] = useState({ open: false, title: '', src: '' });

   const handleSearch = (q) => setSearchQuery(q);

   const fetchNodes = async () => {
     setIsLoading(true);
     setError('');
     try {
       const res = await api.get('/api/dve-nodes');
       const raw = res.data;
-      const allNodes = Array.isArray(raw?.data || raw?.nodes || raw) ? (raw?.data || raw?.nodes || raw) : [];
-      // Strict filter: only nodes with status === 'online' are shown
-      setActiveNodes(allNodes.filter(n => n && n.status === 'online'));
+      const nodes = Array.isArray(raw?.data || raw?.nodes || raw) ? (raw?.data || raw?.nodes || raw) : [];
+      setAllNodes(nodes);
+      // Only show nodes with status === 'online' (active DVEs)
+      setActiveNodes(nodes.filter(n => n && n.status === 'online'));
     } catch (e) {
       console.error('Failed to fetch DVE nodes:', e);
       setError('Could not load DVE nodes. Ensure KNIRVSERVER backend is running.');
       setActiveNodes([]);
+      setAllNodes([]);
     } finally {
       setIsLoading(false);
     }
   };

+  // Fetch on mount and auto-refresh every 10 seconds so newly activated
+  // DVEs appear without a manual page reload.
   useEffect(() => {
     fetchNodes();
+    const interval = setInterval(fetchNodes, 10_000);
+    return () => clearInterval(interval);
   }, []);

   const openDVEExplorer = (node) => {
     setModal({
       open: true,
       title: `DVE File Manager — ${node.name || node.id}`,
       src: `/dve/${encodeURIComponent(node.id)}`,
     });
   };

   const closeModal = () => {
     setModal({ open: false, title: '', src: '' });
   };

   const filtered = activeNodes.filter((n) =>
     [n.name, n.id, n.status, n.tee_type, n.location]
       .filter(Boolean)
       .join(' ')
       .toLowerCase()
       .includes(searchQuery.toLowerCase())
   );

   return (
     <PageLayout activePage={activePage} pageTitle="My DVEs" onSearch={handleSearch}>
       <PageHeader
         title="My DVEs"
-        subtitle={`${activeNodes.length} actively accessible DVE${activeNodes.length !== 1 ? 's' : ''} — activated by admin`}
+        subtitle={`${activeNodes.length} active DVE${activeNodes.length !== 1 ? 's' : ''} — ${allNodes.length} total registered`}
         titleColor="#7c4dff"
       />

       {/* Stats bar */}
       <div className={styles.statsBar}>
         <div className={styles.statCard}>
           <span className={styles.statValue} style={{ color: '#4caf50' }}>{activeNodes.length}</span>
           <span className={styles.statLabel}>Active DVEs</span>
         </div>
         <div className={styles.statCard}>
+          <span className={styles.statValue} style={{ color: '#7c4dff' }}>{allNodes.length}</span>
+          <span className={styles.statLabel}>Total Registered</span>
+        </div>
+        <div className={styles.statCard}>
           <button className={styles.refreshBtn} onClick={fetchNodes} title="Refresh">
             ↻ Refresh
           </button>
         </div>
       </div>

       {/* Loading state */}
       {isLoading && (
         <div className={styles.centerState}>
           <div className={styles.spinner}></div>
           <p>Loading active DVE nodes...</p>
         </div>
       )}

       {/* Error state */}
       {error && !isLoading && (
         <GlassyCard darker className={styles.centerState}>
           <div className={styles.errorIcon}>⚠️</div>
           <p className={styles.errorText}>{error}</p>
           <button className={styles.retryBtn} onClick={fetchNodes}>Retry</button>
         </GlassyCard>
       )}

-      {/* Empty state — no active DVEs */}
+      {/* Empty state — no online DVEs */}
       {!isLoading && !error && filtered.length === 0 && (
         <GlassyCard className={styles.centerState}>
           <div className={styles.emptyIcon}>🖥️</div>
           <h3>No active DVEs</h3>
           <p>
             {searchQuery
               ? 'No active DVEs match your search.'
-              : 'No DVEs are currently active. An admin needs to activate a DVE from the backend or admin dashboard before it appears here.'}
+              : allNodes.length > 0
+                ? `${allNodes.length} DVE node${allNodes.length !== 1 ? 's' : ''} registered but none are online. Activate a DVE from the KNIRVSERVER backend dashboard to see it here.`
+                : 'No DVEs are registered. Use the KNIRVSERVER dashboard to create a new sovereign DVE.'}
           </p>
         </GlassyCard>
       )}

       {/* DVE Grid — only active/online nodes */}
       {!isLoading && !error && filtered.length > 0 && (
         <div className={styles.grid}>
           {filtered.map((node) => (
             <GlassyCard key={node.id} className={styles.card} onClick={() => openDVEExplorer(node)}>
               <div className={styles.cardHeader}>
                 <div className={styles.cardTitleRow}>
                   <span className={styles.teeIcon}>
                     {TEE_ICONS[node.tee_type] || '📦'}
                   </span>
                   <div>
                     <div className={styles.cardTitle}>{node.name || node.id}</div>
                     <div className={styles.cardId}>ID: {node.id.substring(0, 12)}...</div>
                   </div>
                 </div>
                 <span
                   className={styles.statusBadge}
                   style={{
                     background: '#4caf5020',
                     color: '#4caf50',
                     borderColor: '#4caf5040',
                   }}
                 >
                   active
                 </span>
               </div>

               <div className={styles.cardBody}>
                 <div className={styles.detailRow}>
                   <span className={styles.detailLabel}>TEE</span>
                   <span className={styles.detailValue}>{node.tee_type || '—'}</span>
                 </div>
                 <div className={styles.detailRow}>
                   <span className={styles.detailLabel}>Score</span>
                   <span className={styles.detailValue}>{node.reputation_score ?? '—'}</span>
                 </div>
                 {node.location && (
                   <div className={styles.detailRow}>
                     <span className={styles.detailLabel}>Location</span>
                     <span className={styles.detailValue}>{node.location}</span>
                   </div>
                 )}
                 {node.ip_address && (
                   <div className={styles.detailRow}>
                     <span className={styles.detailLabel}>Endpoint</span>
                     <span className={styles.detailValueMono}>{node.ip_address}</span>
                   </div>
                 )}
               </div>

               <div className={styles.cardFooter}>
                 <span className={styles.launchBtn} onClick={(e) => { e.stopPropagation(); openDVEExplorer(node); }}>
                   Open DVE Explorer →
                 </span>
               </div>
             </GlassyCard>
           ))}
         </div>
       )}

       {/* DVE Explorer Modal */}
       {modal.open && (
         <IframeModal title={modal.title} src={modal.src} onClose={closeModal} height="90vh" />
       )}
     </PageLayout>
   );
 }

Index: packages/KNIRVHASHER/pipeline/1_DATA_MINER/spacy/cpp/spacy_wrapper.cpp
===================================================================
--- packages/KNIRVHASHER/pipeline/1_DATA_MINER/spacy/cpp/spacy_wrapper.cpp	
+++ packages/KNIRVHASHER/pipeline/1_DATA_MINER/spacy/cpp/spacy_wrapper.cpp	
@@ -1,960 +1,972 @@
 #include <Python.h>
 #include <string>
 #include <vector>
 #include <memory>
 #include <iostream>
 #include <cstring>
 #include <mutex>
 #include <map>
 #include <thread>
 #include "spacy_wrapper.h"

 // Global state for Python
 static bool g_python_initialized = false;
 static std::mutex g_init_mutex;
 static PyObject* g_spacy_module = nullptr;
 static std::map<std::string, PyObject*> g_nlp_models;
 static std::mutex g_models_mutex;
 static PyThreadState* g_main_thread_state = nullptr;

 class ScopedGIL {
 public:
     ScopedGIL() {
         gstate = PyGILState_Ensure();
     }
     ~ScopedGIL() {
         PyGILState_Release(gstate);
     }
 private:
     PyGILState_STATE gstate;
 };

 // Internal structures
 struct Chunk {
     std::string text;
     std::string root_text;
     std::string root_dep;
     int start;
     int end;
 };

 struct VectorData {
     std::vector<double> vector;
     size_t size;
     bool has_vector;
 };

 struct MorphFeature {
     std::string key;
     std::string value;
 };

 class SpacyWrapper {
 private:
     PyObject* nlp;
     std::string model_name;

 public:
     SpacyWrapper(const char* model) : nlp(nullptr), model_name(model) {
         ScopedGIL gil;

         // Check if model is already loaded
         {
             std::lock_guard<std::mutex> lock(g_models_mutex);
             auto it = g_nlp_models.find(model_name);
             if (it != g_nlp_models.end()) {
                 nlp = it->second;
                 Py_INCREF(nlp);
                 return;
             }
         }

         // Load the model
         PyObject* loadFunc = PyObject_GetAttrString(g_spacy_module, "load");
         if (!loadFunc) {
             PyErr_Print();
             throw std::runtime_error("Failed to get spacy.load function");
         }

         PyObject* args = PyTuple_Pack(1, PyUnicode_FromString(model));
         nlp = PyObject_CallObject(loadFunc, args);
         Py_DECREF(args);
         Py_DECREF(loadFunc);

         if (!nlp) {
             PyErr_Print();
             throw std::runtime_error("Failed to load spacy model");
         }

         // Cache the model
         {
             std::lock_guard<std::mutex> lock(g_models_mutex);
             g_nlp_models[model_name] = nlp;
             Py_INCREF(nlp); // Keep a reference for the cache
         }
     }

     ~SpacyWrapper() {
         if (nlp) {
             ScopedGIL gil;
             Py_DECREF(nlp);
         }
     }

     std::vector<Token> tokenize(const std::string& text) {
         ScopedGIL gil;
         std::vector<Token> tokens;

         PyObject* pyText = PyUnicode_FromString(text.c_str());
         PyObject* doc = PyObject_CallFunctionObjArgs(nlp, pyText, NULL);

         if (!doc) {
             PyErr_Print();
             Py_DECREF(pyText);
             return tokens;
         }

         PyObject* iterator = PyObject_GetIter(doc);
         PyObject* token;

         while ((token = PyIter_Next(iterator))) {
             Token t;

             PyObject* textAttr = PyObject_GetAttrString(token, "text");
             if (textAttr) {
                 const char* val = PyUnicode_AsUTF8(textAttr);
                 if (val) t.text = val;
                 Py_DECREF(textAttr);
             }

             PyObject* lemmaAttr = PyObject_GetAttrString(token, "lemma_");
             if (lemmaAttr) {
                 const char* val = PyUnicode_AsUTF8(lemmaAttr);
                 if (val) t.lemma = val;
                 Py_DECREF(lemmaAttr);
             }

             PyObject* posAttr = PyObject_GetAttrString(token, "pos_");
             if (posAttr) {
                 const char* val = PyUnicode_AsUTF8(posAttr);
                 if (val) t.pos = val;
                 Py_DECREF(posAttr);
             }

             PyObject* tagAttr = PyObject_GetAttrString(token, "tag_");
             if (tagAttr) {
                 const char* val = PyUnicode_AsUTF8(tagAttr);
                 if (val) t.tag = val;
                 Py_DECREF(tagAttr);
             }

             PyObject* depAttr = PyObject_GetAttrString(token, "dep_");
             if (depAttr) {
                 const char* val = PyUnicode_AsUTF8(depAttr);
                 if (val) t.dep = val;
                 Py_DECREF(depAttr);
             }

             PyObject* isStopAttr = PyObject_GetAttrString(token, "is_stop");
             if (isStopAttr) {
                 t.is_stop = PyObject_IsTrue(isStopAttr);
                 Py_DECREF(isStopAttr);
             }

             PyObject* isPunctAttr = PyObject_GetAttrString(token, "is_punct");
             if (isPunctAttr) {
                 t.is_punct = PyObject_IsTrue(isPunctAttr);
                 Py_DECREF(isPunctAttr);
             }

             PyObject* idxAttr = PyObject_GetAttrString(token, "idx");
             if (idxAttr) {
                 t.start = PyLong_AsLong(idxAttr);
                 Py_DECREF(idxAttr);
             }

             PyObject* endAttr = PyLong_FromLong(t.start + (t.text.length()));
             if (endAttr) {
                 t.end = PyLong_AsLong(endAttr);
                 Py_DECREF(endAttr);
             }

             tokens.push_back(t);
             Py_DECREF(token);
         }

         Py_DECREF(iterator);
         Py_DECREF(doc);
         Py_DECREF(pyText);

         return tokens;
     }

     std::vector<Entity> extractEntities(const std::string& text) {
         ScopedGIL gil;
         std::vector<Entity> entities;

         PyObject* pyText = PyUnicode_FromString(text.c_str());
         PyObject* doc = PyObject_CallFunctionObjArgs(nlp, pyText, NULL);

         if (!doc) {
             PyErr_Print();
             Py_DECREF(pyText);
             return entities;
         }

         PyObject* ents = PyObject_GetAttrString(doc, "ents");
         if (!ents) {
             Py_DECREF(doc);
             Py_DECREF(pyText);
             return entities;
         }

         PyObject* iterator = PyObject_GetIter(ents);
         PyObject* ent;

         while ((ent = PyIter_Next(iterator))) {
             Entity e;

             PyObject* textAttr = PyObject_GetAttrString(ent, "text");
             if (textAttr) {
                 const char* val = PyUnicode_AsUTF8(textAttr);
                 if (val) e.text = val;
                 Py_DECREF(textAttr);
             }

             PyObject* labelAttr = PyObject_GetAttrString(ent, "label_");
             if (labelAttr) {
                 const char* val = PyUnicode_AsUTF8(labelAttr);
                 if (val) e.label = val;
                 Py_DECREF(labelAttr);
             }

             PyObject* startAttr = PyObject_GetAttrString(ent, "start_char");
             if (startAttr) {
                 e.start = PyLong_AsLong(startAttr);
                 Py_DECREF(startAttr);
             }

             PyObject* endAttr = PyObject_GetAttrString(ent, "end_char");
             if (endAttr) {
                 e.end = PyLong_AsLong(endAttr);
                 Py_DECREF(endAttr);
             }

             entities.push_back(e);
             Py_DECREF(ent);
         }

         Py_DECREF(iterator);
         Py_DECREF(ents);
         Py_DECREF(doc);
         Py_DECREF(pyText);

         return entities;
     }

     std::vector<std::string> splitSentences(const std::string& text) {
         ScopedGIL gil;
         std::vector<std::string> sentences;

         PyObject* pyText = PyUnicode_FromString(text.c_str());
         PyObject* doc = PyObject_CallFunctionObjArgs(nlp, pyText, NULL);

         if (!doc) {
             PyErr_Print();
             Py_DECREF(pyText);
             return sentences;
         }

         PyObject* sents = PyObject_GetAttrString(doc, "sents");
         if (!sents) {
             Py_DECREF(doc);
             Py_DECREF(pyText);
             return sentences;
         }

         PyObject* iterator = PyObject_GetIter(sents);
         PyObject* sent;

         while ((sent = PyIter_Next(iterator))) {
             PyObject* textAttr = PyObject_GetAttrString(sent, "text");
             if (textAttr) {
                 const char* val = PyUnicode_AsUTF8(textAttr);
                 if (val) sentences.push_back(val);
                 Py_DECREF(textAttr);
             }
             Py_DECREF(sent);
         }

         Py_DECREF(iterator);
         Py_DECREF(sents);
         Py_DECREF(doc);
         Py_DECREF(pyText);

         return sentences;
     }

     std::vector<Chunk> getNounChunks(const std::string& text) {
         ScopedGIL gil;
         std::vector<Chunk> chunks;

         PyObject* pyText = PyUnicode_FromString(text.c_str());
         PyObject* doc = PyObject_CallFunctionObjArgs(nlp, pyText, NULL);

         if (!doc) {
             PyErr_Print();
             Py_DECREF(pyText);
             return chunks;
         }

         PyObject* noun_chunks = PyObject_GetAttrString(doc, "noun_chunks");
         if (!noun_chunks) {
             Py_DECREF(doc);
             Py_DECREF(pyText);
             return chunks;
         }

         PyObject* iterator = PyObject_GetIter(noun_chunks);
         PyObject* chunk;

         while ((chunk = PyIter_Next(iterator))) {
             Chunk c;

             PyObject* textAttr = PyObject_GetAttrString(chunk, "text");
             if (textAttr) {
                 const char* val = PyUnicode_AsUTF8(textAttr);
                 if (val) c.text = val;
                 Py_DECREF(textAttr);
             }

             PyObject* rootAttr = PyObject_GetAttrString(chunk, "root");
             if (rootAttr) {
                 PyObject* rootText = PyObject_GetAttrString(rootAttr, "text");
                 if (rootText) {
                     const char* val = PyUnicode_AsUTF8(rootText);
                     if (val) c.root_text = val;
                     Py_DECREF(rootText);
                 }
                 PyObject* rootDep = PyObject_GetAttrString(rootAttr, "dep_");
                 if (rootDep) {
                     const char* val = PyUnicode_AsUTF8(rootDep);
                     if (val) c.root_dep = val;
                     Py_DECREF(rootDep);
                 }
                 Py_DECREF(rootAttr);
             }

             PyObject* startAttr = PyObject_GetAttrString(chunk, "start_char");
             if (startAttr) {
                 c.start = PyLong_AsLong(startAttr);
                 Py_DECREF(startAttr);
             }

             PyObject* endAttr = PyObject_GetAttrString(chunk, "end_char");
             if (endAttr) {
                 c.end = PyLong_AsLong(endAttr);
                 Py_DECREF(endAttr);
             }

             chunks.push_back(c);
             Py_DECREF(chunk);
         }

         Py_DECREF(iterator);
         Py_DECREF(noun_chunks);
         Py_DECREF(doc);
         Py_DECREF(pyText);

         return chunks;
     }

     VectorData getVector(const std::string& text) {
         ScopedGIL gil;
         VectorData vecData;
         vecData.vector.clear();
         vecData.size = 0;
         vecData.has_vector = false;

         PyObject* pyText = PyUnicode_FromString(text.c_str());
         PyObject* doc = PyObject_CallFunctionObjArgs(nlp, pyText, NULL);

         if (!doc) {
             PyErr_Print();
             Py_DECREF(pyText);
             return vecData;
         }

         PyObject* hasVecAttr = PyObject_GetAttrString(doc, "has_vector");
         if (hasVecAttr) {
             vecData.has_vector = PyObject_IsTrue(hasVecAttr);
             Py_DECREF(hasVecAttr);
         }

         if (vecData.has_vector) {
             PyObject* vectorAttr = PyObject_GetAttrString(doc, "vector");
             if (vectorAttr) {
                 // Convert numpy array to C array
                 PyObject* listObj = PyObject_CallMethod(vectorAttr, "tolist", NULL);
                 if (listObj && PyList_Check(listObj)) {
                     Py_ssize_t size = PyList_Size(listObj);
                     vecData.size = size;
                     vecData.vector.resize(size);

                     for (Py_ssize_t i = 0; i < size; i++) {
                         PyObject* item = PyList_GetItem(listObj, i);
                         vecData.vector[i] = PyFloat_AsDouble(item);
                     }
                     Py_DECREF(listObj);
                 }
                 Py_DECREF(vectorAttr);
             }
         }

         Py_DECREF(doc);
         Py_DECREF(pyText);

         return vecData;
     }

     double getSimilarity(const std::string& text1, const std::string& text2) {
         ScopedGIL gil;

         PyObject* pyText1 = PyUnicode_FromString(text1.c_str());
         PyObject* doc1 = PyObject_CallFunctionObjArgs(nlp, pyText1, NULL);

         if (!doc1) {
             PyErr_Print();
             Py_DECREF(pyText1);
             return 0.0;
         }

         PyObject* pyText2 = PyUnicode_FromString(text2.c_str());
         PyObject* doc2 = PyObject_CallFunctionObjArgs(nlp, pyText2, NULL);

         if (!doc2) {
             PyErr_Print();
             Py_DECREF(doc1);
             Py_DECREF(pyText1);
             Py_DECREF(pyText2);
             return 0.0;
         }

         double similarity = 0.0;
         PyObject* simMethod = PyObject_GetAttrString(doc1, "similarity");
         if (simMethod) {
             PyObject* args = PyTuple_Pack(1, doc2);
             PyObject* result = PyObject_CallObject(simMethod, args);
             if (result) {
                 similarity = PyFloat_AsDouble(result);
                 Py_DECREF(result);
             }
             Py_DECREF(args);
             Py_DECREF(simMethod);
         }

         Py_DECREF(doc2);
         Py_DECREF(pyText2);
         Py_DECREF(doc1);
         Py_DECREF(pyText1);

         return similarity;
     }

     std::vector<MorphFeature> getMorphology(const std::string& text) {
         ScopedGIL gil;
         std::vector<MorphFeature> morphFeatures;

         PyObject* pyText = PyUnicode_FromString(text.c_str());
         PyObject* doc = PyObject_CallFunctionObjArgs(nlp, pyText, NULL);

         if (!doc) {
             PyErr_Print();
             Py_DECREF(pyText);
             return morphFeatures;
         }

         PyObject* iterator = PyObject_GetIter(doc);
         PyObject* token;

         while ((token = PyIter_Next(iterator))) {
             PyObject* morphAttr = PyObject_GetAttrString(token, "morph");
             if (morphAttr) {
                 PyObject* strMethod = PyObject_GetAttrString(morphAttr, "__str__");
                 if (strMethod) {
                     PyObject* morphStr = PyObject_CallObject(strMethod, NULL);
                     if (morphStr) {
                         const char* morphText = PyUnicode_AsUTF8(morphStr);
                         if (!morphText) {
                             Py_DECREF(morphStr);
                             Py_DECREF(strMethod);
                             Py_DECREF(morphAttr);
                             Py_DECREF(token);
                             continue;
                         }
                         // Parse morph string (e.g., "Case=Nom|Number=Sing")
                         std::string morphString(morphText);
                         if (!morphString.empty()) {
                             // For simplicity, store the entire morph string as one feature
                             MorphFeature feature;
                             feature.key = "morph";
                             feature.value = morphString;
                             morphFeatures.push_back(feature);
                         }
                         Py_DECREF(morphStr);
                     }
                     Py_DECREF(strMethod);
                 }
                 Py_DECREF(morphAttr);
             }
             Py_DECREF(token);
         }

         Py_DECREF(iterator);
         Py_DECREF(doc);
         Py_DECREF(pyText);

         return morphFeatures;
     }
 };

 // Global wrapper instance with mutex protection
 static std::unique_ptr<SpacyWrapper> g_wrapper;
 static std::mutex g_wrapper_mutex;

 extern "C" {

 int spacy_init(const char* model_name) {
     if (!model_name || strlen(model_name) == 0) {
         std::cerr << "Error: model_name is null or empty" << std::endl;
         return -1;
     }

     // Initialize Python if needed
     {
         std::lock_guard<std::mutex> lock(g_init_mutex);
         if (!g_python_initialized) {
             Py_Initialize();

             // Save the main thread state and release GIL
             // PyEval_InitThreads() is automatic in Python 3.7+
             g_main_thread_state = PyEval_SaveThread();
             g_python_initialized = true;
         }
     }

     try {
         // Ensure GIL is held for this thread
         ScopedGIL gil;

         // Import spacy if not already done
         if (!g_spacy_module) {
             // Setup Python path
             PyObject* sys = PyImport_ImportModule("sys");
             if (sys) {
                 PyObject* path = PyObject_GetAttrString(sys, "path");
                 if (path) {
                     PyList_Append(path, PyUnicode_FromString("."));
