     if (arr && arr->tokens) {
         for (size_t i = 0; i < arr->count; ++i) {
             free((void*)arr->tokens[i].text);
             free((void*)arr->tokens[i].lemma);
             free((void*)arr->tokens[i].pos);
             free((void*)arr->tokens[i].tag);
             free((void*)arr->tokens[i].dep);
